arguments.command:
python3 - <<'EOF'
from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Valid event
    try:
        ServerSentEvent(event="test_event", id="test_id")
        print("Valid event passed")
    except ValidationError as e:
        print(f"Valid event failed: {e}")

    # Invalid event (newline)
    try:
        ServerSentEvent(event="test\nevent")
        print("Invalid event (newline) passed")
    except ValidationError as e:
        print(f"Invalid event (newline) failed as expected: {e}")

    # Invalid event (carriage return)
    try:
        ServerSentEvent(event="test\revent")
        print("Invalid event (carriage return) passed")
    except ValidationError as e:
        print(f"Invalid event (carriage return) failed as expected: {e}")

    # Invalid id (newline)
    try:
        ServerSentEvent(id="test\nid")
        print("Invalid id (newline) passed")
    except ValidationError as e:
        print(f"Invalid id (newline) failed as expected: {e}")

    # Invalid id (carriage return)
    try:
        ServerSentEvent(id="test\rid")
        print("Invalid id (carriage return) passed")
    except ValidationError as e:
        print(f"Invalid id (carriage return) failed as expected: {e}")

    # Invalid id (null character)
    try:
        ServerSentEvent(id="test\0id")
        print("Invalid id (null) passed")
    except ValidationError as e:
        print(f"Invalid id (null) failed as expected: {e}")

test_sse_validation()
EOF
